#!/usr/bin/env python3
import sys


def make_divisors(n):
    divisors = []
    for i in range(1, int(n**0.5)+1):
        if n % i == 0:
            divisors.append(i)
            if i != n // i:
                divisors.append(n//i)
    return divisors


def solve(N: int):
    ndiv = make_divisors(N)
    count = 0
    for div in ndiv:
        if div == 1:
            continue
        n = N
        while n % div == 0:
            n //= div
        if n % div == 1:
            count += 1
    print(len(make_divisors(N-1))+count-1)
    return


# Generated by 1.1.6 https://github.com/kyuridenamida/atcoder-tools  (tips: You use the default template now. You can remove this line by using your custom template)
def main():
    def iterate_tokens():
        for line in sys.stdin:
            for word in line.split():
                yield word
    tokens = iterate_tokens()
    N = int(next(tokens))  # type: int
    solve(N)


if __name__ == '__main__':
    main()
